  if (!args[0] || args[0].startsWith('--')) { console.error('Usage: bun sa-export-assemble.js <project-root> [--lang en|es] [--slug <slug>] [--suffix <-xx>] [--out-dir <dir>] [--plain <file>] [--risk-summaries <file>] [--parts] [--json] [--judge agent|typesafe|clef]'); process.exit(2); }
