  if (args.includes('--parts')) { const pd = path.join(outDir, 'parts'); fs.rmSync(pd, { recursive: true, force: true }); fs.mkdirSync(pd, { recursive: true }); fs.writeFileSync(path.join(pd, 'briefing-00.md'), r.briefingHead.trimEnd() + '\n\n'); fs.writeFileSync(path.join(pd, 'briefing-99.md'), '\n' + r.briefingTail.trimStart()); fs.writeFileSync(path.join(pd, 'reference-00.md'), r.referenceHead.trimEnd() + '\n\n'); r.briefingParts.forEach((p, i) => fs.writeFileSync(path.join(pd, `briefing-${String(i + 1).padStart(2, '0')}.md`), `## ${p.title} <!-- SECTION: ${p.anchor} -->\n\n${decomment(unlink(render(p.blocks))).trim()}\n`)); r.referenceParts.forEach((p, i) => fs.writeFileSync(path.join(pd, `reference-${String(i + 1).padStart(2, '0')}.md`), `## ${p.title} <!-- SECTION: ${p.anchor} -->\n\n${decomment(render(p.blocks)).trim()}\n`)); }
  if (args.includes('--json')) console.log(JSON.stringify({ name: r.name, slug: r.slug, lang: r.lang, version: r.version, status: r.status, briefing_bytes: Buffer.byteLength(r.briefing), reference_bytes: Buffer.byteLength(r.reference), report: r.report }, null, 1));
  console.error(`Wrote ${outDir}/sa-briefing.md (${kb(r.briefing)}) and sa-reference.md (${kb(r.reference)}) — ${r.name} v${r.version} ${r.status}, ${r.lang}, slug ${r.slug}`);
  console.error(`Sources: ${Object.entries(r.report.sources).map(([k, v]) => (v ? '✓ ' : '✗ ') + k).join(' · ')}`);
  console.error(`Routed (${r.report.routed.length}): ${r.report.routed.join('; ')}`);
  console.error(`Decisions Pending: ${r.report.pending}`);
  const rs = r.report.risk_summaries; if (rs && rs.requested.length) { const req = path.join(outDir, 'risk-summaries.request.json'); fs.writeFileSync(req, JSON.stringify({ lang: r.lang, max_chars: rs.max_chars, rows: rs.requested }, null, 1)); console.error(opt('--risk-summaries') ? `Risk summaries: ${rs.applied}/${rs.requested.length} applied${rs.issues.length ? ' — REFUSED: ' + rs.issues.join('; ') : ''}` : `Risk summaries: ${rs.requested.length} critical row(s) still verbatim — rewrite each Risk and Mitigation for a non-technical forum (≤ ${rs.max_chars} chars, from the row, nothing invented) into risk-summaries.json ({ rows: [{ key, risk_plain, mitigation_plain }] }) next to ${req} and re-run with --risk-summaries <that file>`); }
  const pl = r.report.plain; if (pl) {
    const req = path.join(outDir, 'plain-language.request.json');
    fs.writeFileSync(req, JSON.stringify({ lang: r.lang, name: r.name, max_chars: pl.max_chars, one_page: pl.requested.one_page, metrics: pl.requested.metrics, leads: pl.requested.leads }, null, 1));
    const want = 4 + pl.requested.leads.length;
    console.error(opt('--plain')
      ? `Plain language: ${pl.applied} slot(s) applied${pl.issues.length ? ' — REFUSED: ' + pl.issues.join('; ') : ''}`
      : `Plain language: 0 of ~${want} slot(s) composed — the briefing opens on the Problem Statement instead of a one-page summary, subsections open straight into their table, and there is no metrics table. Write plain-language.json ({ one_page: { what, why, how, decide }, metrics: [{ label, value }], leads: [{ key, text }] }) next to ${req} and re-run with --plain <that file>`);
  }
  const un = r.report.layer_names_undecided || []; if (un.length) console.error(`Layer names UNDECIDED (${un.length}) — printed as written, bound to no component: ${un.map((n) => `"${n}"`).join(', ')} — ${r.report.layer_names_worksheet ? `answer ${r.report.layer_names_worksheet} and re-run` : `the judge failed (${r.report.judge_note || 'no answer'})`}`);
